import { useState } from 'react';
import {
  Card,
  Stack,
  Cluster,
  Heading,
  Text,
  Badge,
  Divider,
  SegmentedControl,
  Segment,
  Slider,
  Switch,
  Select,
  Option,
  Field,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'default' | 'compact' | 'rounded';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  denseLayout: boolean;
  font: Font;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState<number>(100);
  const [denseLayout, setDenseLayout] = useState<boolean>(false);
  const [font, setFont] = useState<Font>('default');

  const emit = (next: Partial<AppearanceSettings>) => {
    const settings: AppearanceSettings = {
      theme,
      scale,
      denseLayout,
      font,
      ...next,
    };
    onChange?.(settings);
  };

  const handleThemeChange = (value: Theme) => {
    setTheme(value);
    emit({ theme: value });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleDenseChange = (value: boolean) => {
    setDenseLayout(value);
    emit({ denseLayout: value });
  };

  const handleFontChange = (value: Font) => {
    setFont(value);
    emit({ font: value });
  };

  return (
    <Card style={{ padding: 'var(--jx-space-6)' }}>
      <Stack gap="var(--jx-space-6)">
        <Cluster justify="space-between" align="center">
          <Heading level={2}>Внешний вид</Heading>
          <Badge variant="secondary">{themeLabels[theme]}</Badge>
        </Cluster>

        <Field label="Тема">
          <SegmentedControl
            value={theme}
            onChange={(value) => handleThemeChange(value as Theme)}
          >
            <Segment value="light">Светлая</Segment>
            <Segment value="dark">Тёмная</Segment>
            <Segment value="system">Системная</Segment>
          </SegmentedControl>
        </Field>

        <Field label="Масштаб интерфейса">
          <Cluster gap="var(--jx-space-4)" align="center">
            <Slider
              min={80}
              max={140}
              step={5}
              value={scale}
              onChange={(value) => handleScaleChange(value as number)}
              style={{ flex: 1 }}
            />
            <Text tone="secondary" style={{ minWidth: '3.5rem', textAlign: 'right' }}>
              {scale}%
            </Text>
          </Cluster>
        </Field>

        <Cluster justify="space-between" align="center">
          <Stack gap="var(--jx-space-1)">
            <Text weight="medium">Плотная вёрстка</Text>
            <Text tone="secondary" size="sm">
              Уменьшает отступы между элементами интерфейса
            </Text>
          </Stack>
          <Switch checked={denseLayout} onChange={handleDenseChange} />
        </Cluster>

        <Divider />

        <Stack gap="var(--jx-space-4)">
          <Heading level={3}>Ещё</Heading>

          <Field label="Шрифт">
            <Select
              value={font}
              onChange={(value) => handleFontChange(value as Font)}
            >
              <Option value="default">По умолчанию</Option>
              <Option value="compact">Компактный</Option>
              <Option value="rounded">Скруглённый</Option>
            </Select>
          </Field>
        </Stack>
      </Stack>
    </Card>
  );
}

